(() => {
 const data=JSON.parse(document.getElementById('quote-copy-data').textContent),form=document.getElementById('quote-form'),ready=document.getElementById('qp-ready'),emailLink=document.getElementById('qp-email-link'),copyStatus=document.getElementById('qp-copy-status'),fallback=document.getElementById('qp-draft-fallback');
 let files=[],draft='',prepared=false;
 const isSample=data.mode==='sample',isConsult=data.mode==='consult',hasSamples=isSample||isConsult;let chosenModels=[],referenceManaged=false;
 const lang=()=>document.documentElement.lang.startsWith('zh')?'zh':document.documentElement.lang==='en'?'en':'vi';
 const local=s=>lang()==='zh'?HOTPRINT_I18N.translate(s):s;
 const text=key=>local(data.copy[key][lang()==='vi'?0:1]);
 const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
 const groupSlugs=new Set(['unknown',...data.groups.map(g=>g[0])]);
 if(form.elements.deadline)form.elements.deadline.min=today();
 const timezones=isConsult?[...new Set(['Asia/Ho_Chi_Minh','UTC','Asia/Singapore','Asia/Tokyo','Australia/Sydney','Europe/London','America/New_York',...(Intl.supportedValuesOf?.('timeZone')||[])])]:[];
 function zonedNow(zone){const parts=new Intl.DateTimeFormat('en-US',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date()),v=Object.fromEntries(parts.map(p=>[p.type,p.value]));return {date:`${v.year}-${v.month}-${v.day}`,time:`${v.hour}:${v.minute}`}}
 function zoneOffset(zone){return new Intl.DateTimeFormat('en-US',{timeZone:zone,timeZoneName:'shortOffset'}).formatToParts(new Date()).find(p=>p.type==='timeZoneName').value.replace('GMT','UTC')}
 function updateSchedule(){if(!isConsult)return;const zone=form.elements.timezone.value;if(!timezones.includes(zone))return;form.elements.date.min=zonedNow(zone).date;document.getElementById('consult-zone-summary').textContent=(zone==='Asia/Ho_Chi_Minh'?text('zoneVietnam'):zone==='UTC'?text('zoneUniversal'):zone)+' · '+zoneOffset(zone)+(zone==='Asia/Ho_Chi_Minh'||zone==='UTC'?'':' ('+text('currentOffset')+')');const inPerson=form.elements.format.value==='inperson';document.getElementById('consult-location').hidden=!inPerson;document.getElementById('consult-online').hidden=form.elements.format.value!=='online';document.getElementById('consult-location-address').textContent=inPerson?({office:'9B Đường 1A, KCN Biên Hòa 2, Đồng Nai.',factory:'999 Nguyễn Thiện Thuật, KP1, Phường An Hoà, Biên Hoà, Đồng Nai.'}[form.elements.location.value]||''):''}
 function clearErrors(){form.querySelectorAll('[aria-invalid]').forEach(el=>el.removeAttribute('aria-invalid'));form.querySelectorAll('.qp-error:not(#q-error-files)').forEach(el=>{el.textContent='';delete el.dataset.errorKey})}
 function error(name,key){const note=document.getElementById('q-error-'+name);form.querySelectorAll(`[name="${name}"]`).forEach(el=>el.setAttribute('aria-invalid','true'));note.textContent=text(key);note.dataset.errorKey=key}
 function updateCount(){const locale=lang()==='vi'?'vi-VN':'en-US';document.getElementById('qp-message-count').textContent=form.elements.message.value.length.toLocaleString(locale)+' / '+(3000).toLocaleString(locale)}
 function fileList(){const list=document.getElementById('q-file-list');list.replaceChildren();files.forEach((file,index)=>{const li=document.createElement('li'),label=document.createElement('span'),button=document.createElement('button');label.textContent=`${file.name} · ${(file.size/1024/1024).toFixed(2)} MB`;button.type='button';button.textContent=text('removeFile');button.setAttribute('aria-label',text('removeFile')+': '+file.name);button.onclick=()=>{files.splice(index,1);fileList();invalidate()};li.append(label,button);list.append(li)})}
 function invalidate(){prepared=false;draft='';ready.hidden=true;fallback.hidden=true;copyStatus.textContent='';emailLink.removeAttribute('href');document.getElementById('qp-status-guide').removeAttribute('href')}
 function renderModels(updateReference=false){if(!hasSamples)return;const tray=document.getElementById('sample-selected'),items=document.getElementById('sample-selected-items');tray.hidden=!chosenModels.length;items.replaceChildren();if(updateReference){form.elements.reference.value=chosenModels.map(p=>p[lang()]+' ('+p.id+')').join('; ');referenceManaged=chosenModels.length>0;}chosenModels.forEach((p,index)=>{const article=document.createElement('article'),img=document.createElement('img'),body=document.createElement('div'),name=document.createElement('p'),ref=document.createElement('small'),remove=document.createElement('button');img.src='/assets/products/'+p.images[0]+'.webp';img.alt=p[lang()];img.width=68;img.height=68;name.textContent=p[lang()];ref.textContent=text('sampleReference')+': '+p.id;remove.type='button';remove.textContent=text('removeSample');remove.setAttribute('aria-label',text('removeSample')+': '+p[lang()]);remove.onclick=()=>{chosenModels.splice(index,1);renderModels(true);invalidate();document.getElementById('q-reference').focus()};body.append(name,ref,remove);article.append(img,body);items.append(article)})}
 function chooseModels(ids){chosenModels=[...new Set(ids)].slice(0,6).map(id=>window.HOTPRINT_PRODUCTS?.find(p=>p.id===id)).filter(Boolean);const map={folding:'hop-giay-mem',carton:'hop-carton',rigid:'hop-cao-cap',bag:'tui-giay',label:'nhan-dan-decal',catalog:'nhan-hang-catalog'};if(chosenModels.length)form.elements.category.value=chosenModels.every(p=>p.group===chosenModels[0].group)?map[chosenModels[0].group]:'unknown';renderModels(true);invalidate()}
 function getValues(){return Object.fromEntries([...new FormData(form)].filter(([,v])=>typeof v==='string').map(([k,v])=>[k,v.trim()]))}
 function prepare(){const v=getValues(),group=local(data.groups.find(g=>g[0]===v.category)?.[lang()==='vi'?1:2]||text('unknown'));
 const details=isConsult?[`${text('topic')}: ${text(data.topics.find(t=>t[0]===v.topic)[1])}`,`${text('consultDate')}: ${v.date||text('unspecified')}`,`${text('timeStart')}: ${v.timeStart||text('unspecified')}`,`${text('timeEnd')}: ${v.timeEnd||text('unspecified')}`,`${text('timezone')}: ${v.timezone}${v.timezone==='Asia/Ho_Chi_Minh'?' (UTC+7)':v.timezone==='UTC'?' (UTC)':''}`,`${text('format')}: ${text({unknown:'formatUnknown',phone:'formatPhone',online:'formatOnline',inperson:'formatInPerson'}[v.format])}`,...(v.format==='inperson'?[`${text('location')}: ${text({unknown:'locationUnknown',office:'locationOffice',factory:'locationFactory',other:'locationOther'}[v.location])}`,document.getElementById('consult-location-address').textContent,`${text('locationDetails')}: ${v.locationDetails||text('unspecified')}`]:[]),...(v.format==='online'?[`${text('onlineInfo')}: ${v.onlineInfo||text('unspecified')}`]:[]),text('scheduleHint')]:[`${text('quantity')}: ${v.quantity||text('unspecified')}`,...(isSample?[`${text('sampleKind')}: ${text({reference:'kindReference',project:'kindProject',advice:'kindAdvice'}[v.kind]||'kindAdvice')}`,`${text('receipt')}: ${text({later:'receiptLater',collect:'receiptCollect',delivery:'receiptDelivery'}[v.receipt]||'receiptLater')}`,...(v.receipt==='delivery'?[`${text('address')}: ${v.address||text('unspecified')}`]:[])]:[`${text('dimensions')}: ${v.dimensions||text('unspecified')}`,`${text('deadline')}: ${v.deadline||text('unspecified')}`])];
 draft=[`${text('name')}: ${v.name}`,`${text('company')}: ${v.company}`,`${local('Email')}: ${v.email||text('unspecified')}`,`${text('phone')}: ${v.phone||text('unspecified')}`,`${text('category')}: ${group}`,`${text('reference')}: ${v.reference||text('unspecified')}`,...details,'',text('message')+':',v.message||text('unspecified'),'',text('attachedFiles')+':',files.length?files.map(f=>'- '+f.name).join('\n'):text('noFile'),'',text('consent'),'',text('source')].join('\n');emailLink.href='mailto:info@hotprint.vn?subject='+encodeURIComponent('HotPrint — '+text('kicker'))+'&body='+encodeURIComponent(draft);document.getElementById('qp-status-guide').href=HOTPRINT_I18N.path('/en/request-status/','/da-gui-yeu-cau/',lang())+'?type='+(isConsult?'consult':isSample?'sample':'quote');if(!fallback.hidden)fallback.value=draft}

 function localize(){document.querySelectorAll('[data-quote-text]').forEach(el=>el.textContent=text(el.dataset.quoteText));document.querySelectorAll('[data-quote-html]').forEach(el=>el.innerHTML=text(el.dataset.quoteHtml));document.querySelectorAll('[data-quote-placeholder]').forEach(el=>el.placeholder=text(el.dataset.quotePlaceholder));const current=form.elements.category.value;form.elements.category.replaceChildren(new Option(text('chooseCategory'),''),new Option(text('unknown'),'unknown'),...data.groups.map(g=>new Option(local(g[lang()==='vi'?1:2]),g[0])));form.elements.category.value=current;form.querySelectorAll('[data-error-key]').forEach(el=>el.textContent=text(el.dataset.errorKey));document.getElementById('q-file-list').setAttribute('aria-label',lang()==='vi'?'Tệp đã chọn':local('Selected files'));fallback.setAttribute('aria-label',lang()==='vi'?'Nội dung yêu cầu để sao chép':local('Request details to copy'));if(isConsult){const zone=form.elements.timezone.value||'Asia/Ho_Chi_Minh';form.elements.timezone.replaceChildren(...timezones.map(z=>new Option(z==='Asia/Ho_Chi_Minh'?text('zoneVietnam')+' — UTC+7':z==='UTC'?text('zoneUniversal')+' — UTC':z.replaceAll('_',' '),z)));form.elements.timezone.value=zone;updateSchedule()}fileList();updateCount();renderModels(referenceManaged);if(prepared)prepare()}
 const params=new URLSearchParams(location.search),model=window.HOTPRINT_PRODUCTS?.find(p=>p.id===params.get('model'));if(groupSlugs.has(params.get('category')))form.elements.category.value=params.get('category');
 if(model){form.elements.reference.value=model[lang()]+' ('+model.id+')';const map={folding:'hop-giay-mem',carton:'hop-carton',rigid:'hop-cao-cap',bag:'tui-giay',label:'nhan-dan-decal',catalog:'nhan-hang-catalog'};form.elements.category.value=map[model.group]||'unknown'}
 if(hasSamples){const ids=model?[model.id]:(params.get('models')||'').split(',');chooseModels(ids);const loadSaved=()=>{try{const ids=JSON.parse(localStorage.getItem('hotprint-sample-selection')||'[]');return Array.isArray(ids)?ids.filter(id=>window.HOTPRINT_PRODUCTS?.some(p=>p.id===id)).slice(0,6):[]}catch{return []}},button=document.getElementById('sample-use-saved');button.hidden=!loadSaved().length;button.onclick=()=>{const saved=loadSaved();button.hidden=!saved.length;if(saved.length)chooseModels(saved)};window.addEventListener('storage',event=>{if(event.key==='hotprint-sample-selection'||event.key===null)button.hidden=!loadSaved().length});if(isSample)form.elements.receipt.addEventListener('change',()=>{document.getElementById('sample-address-field').hidden=form.elements.receipt.value!=='delivery';invalidate()});}
 if(isConsult){if(data.topics.some(t=>t[0]===params.get('topic')))form.elements.topic.value=params.get('topic');if(['unknown','phone','online','inperson'].includes(params.get('format')))form.elements.format.value=params.get('format');if(['unknown','office','factory','other'].includes(params.get('location')))form.elements.location.value=params.get('location');form.addEventListener('change',()=>{updateSchedule();invalidate()})}
 localize();document.addEventListener('hotprint:language',localize);
 form.addEventListener('input',e=>{invalidate();if(hasSamples&&e.target.name==='reference'){chosenModels=[];referenceManaged=false;renderModels()}if(e.target.name==='kind')form.querySelectorAll('[name=kind]').forEach(el=>el.removeAttribute('aria-invalid'));if(e.target.name){e.target.removeAttribute('aria-invalid');const note=document.getElementById('q-error-'+e.target.name);if(note){note.textContent='';delete note.dataset.errorKey}}updateCount()});
 document.getElementById('q-files').addEventListener('change',e=>{const added=[...e.target.files],note=document.getElementById('q-error-files');note.textContent='';delete note.dataset.errorKey;const candidate=[...files,...added].filter((f,i,a)=>a.findIndex(x=>x.name===f.name&&x.size===f.size&&x.lastModified===f.lastModified)===i);const key=candidate.length>3?'filesCountError':added.some(f=>f.size>10*1024*1024||!(/\.(pdf|jpe?g|png)$/i.test(f.name))||(f.type&&!['application/pdf','image/jpeg','image/png'].includes(f.type)))?'filesTypeError':'';if(key){note.textContent=text(key);note.dataset.errorKey=key}else{files=candidate;fileList()}e.target.value='';invalidate()});
 form.addEventListener('submit',e=>{e.preventDefault();clearErrors();const v=getValues(),errors=[];if(v.name.length<2||v.name.length>100)errors.push(['name','nameError']);if(!v.company||v.company.length>150)errors.push(['company','companyError']);if(!v.email&&!v.phone)errors.push(['email','contactError']);if(v.email&&(!form.elements.email.validity.valid||v.email.length>150))errors.push(['email','emailError']);if(v.phone&&(!/^[+\d\s().-]{6,30}$/.test(v.phone)||v.phone.replace(/\D/g,'').length<6))errors.push(['phone','phoneError']);if((!isConsult||v.category)&&!groupSlugs.has(v.category))errors.push(['category','categoryError']);if((!isConsult&&v.message.length<(isSample?10:20))||v.message.length>3000)errors.push(['message','messageError']);if(v.deadline&&v.deadline<today())errors.push(['deadline','deadlineError']);if(isSample&&!['reference','project','advice'].includes(v.kind))errors.push(['kind','kindError']);if(isSample&&!['later','collect','delivery'].includes(v.receipt))errors.push(['receipt','receiptError']);if(isConsult){if(!data.topics.some(t=>t[0]===v.topic))errors.push(['topic','topicError']);if(!['unknown','phone','online','inperson'].includes(v.format))errors.push(['format','formatError']);if(v.format==='inperson'&&!['unknown','office','factory','other'].includes(v.location))errors.push(['location','locationError']);if(!timezones.includes(v.timezone))errors.push(['timezone','zoneError']);else{const now=zonedNow(v.timezone);if(v.date&&v.date<now.date)errors.push(['date','dateError']);if(v.date===now.date&&v.timeStart&&v.timeStart<=now.time)errors.push(['timeStart','pastTimeError']);}if(v.timeEnd&&!v.timeStart)errors.push(['timeStart','timeError']);else if(v.timeStart&&v.timeEnd&&v.timeEnd<=v.timeStart)errors.push(['timeEnd','timeOrderError']);}if(!form.elements.consent.checked)errors.push(['consent','consentError']);if(errors.length){errors.forEach(([name,key])=>error(name,key));if(errors.some(([name])=>name==='deadline'))form.querySelector('details').open=true;form.querySelector('[name="'+errors[0][0]+'"]').focus();return}prepared=true;prepare();ready.hidden=false;copyStatus.textContent='';fallback.hidden=true;emailLink.click()});
 document.getElementById('qp-copy-draft').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(draft);copyStatus.textContent=text('copied');fallback.hidden=true}catch{copyStatus.textContent=text('manualCopy');fallback.value=draft;fallback.hidden=false;fallback.focus();fallback.select()}});
})();
